import { NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { requireFeatureRpc, FeatureGateError } from '@/lib/billing/feature-gate'

export async function GET() {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const supabase = await createClient()

  try {
    await requireFeatureRpc(supabase, authUser.studioId, 'multi_location')
  } catch (err) {
    if (err instanceof FeatureGateError) {
      return NextResponse.json({ error: 'Multi-location requires Pro plan or higher' }, { status: 403 })
    }
    throw err
  }

  try {
    const { data, error } = await supabase.rpc('get_multi_location_overview', {
      p_studio_id: authUser.studioId,
    })

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'multi_location_overview rpc failed')
      return NextResponse.json({ error: 'Failed to load overview' }, { status: 500 })
    }

    return NextResponse.json({ data: data ?? {} })
  } catch (err) {
    logger.error({ err }, 'locations overview unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

export async function GET(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { id: locationId } = await params

  try {
    const supabase = await createClient()

    // Verify location belongs to this studio
    const { data: loc, error: locErr } = await supabase
      .from('locations')
      .select('id')
      .eq('id', locationId)
      .eq('studio_id', authUser.studioId)
      .maybeSingle()

    if (locErr || !loc) {
      return NextResponse.json({ error: 'Location not found' }, { status: 404 })
    }

    const { data, error } = await supabase.rpc('get_location_dashboard', {
      p_location_id: locationId,
    })

    if (error) {
      logger.error({ err: error, locationId }, 'get_location_dashboard rpc failed')
      return NextResponse.json({ error: 'Failed to load dashboard' }, { status: 500 })
    }

    return NextResponse.json({ data: data ?? {} })
  } catch (err) {
    logger.error({ err }, 'location dashboard unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'

const AssignArtistSchema = z.object({
  artist_id: z.string().uuid(),
  is_primary: z.boolean().default(false),
})

const DeleteAssignmentSchema = z.object({
  artist_id: z.string().uuid(),
})

export async function GET(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id: locationId } = await params

  try {
    const supabase = await createClient()

    const { data, error } = await supabase
      .from('location_assignments')
      .select(`
        id, is_primary, created_at,
        artist:artists(id, display_name, avatar_url, status)
      `)
      .eq('location_id', locationId)
      .eq('studio_id', authUser.studioId)
      .order('is_primary', { ascending: false })

    if (error) {
      logger.error({ err: error, locationId }, 'location artists GET failed')
      return NextResponse.json({ error: 'Failed to fetch artists' }, { status: 500 })
    }

    return NextResponse.json({ data: data ?? [] })
  } catch (err) {
    logger.error({ err }, 'location artists GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id: locationId } = await params

  let body: unknown
  try { body = await request.json() } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = AssignArtistSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  try {
    const supabase = await createClient()

    const { data, error } = await supabase
      .from('location_assignments')
      .upsert({
        studio_id: authUser.studioId,
        location_id: locationId,
        artist_id: parsed.data.artist_id,
        is_primary: parsed.data.is_primary,
      }, { onConflict: 'location_id,artist_id' })
      .select()
      .single()

