import { requireFeatureRpc, FeatureGateError } from '@/lib/billing/feature-gate'

const GenerateCodeSchema = z.object({
  client_id: z.string().uuid(),
})

export async function GET() {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const supabase = await createClient()

  try {
    await requireFeatureRpc(supabase, authUser.studioId, 'referral_program')
  } catch (err) {
    if (err instanceof FeatureGateError) {
      return NextResponse.json({ error: 'Referral program requires Studio plan' }, { status: 403 })
    }
    throw err
  }

  try {
    const { data, error } = await supabase
      .from('referral_codes')
      .select(`
        id, code, discount_type, discount_value, referrer_reward_type, referrer_reward_value,
        max_uses, uses_count, is_active, expires_at, created_at,
        client:clients(id, first_name, last_name, email)
      `)
      .eq('studio_id', authUser.studioId)
      .order('created_at', { ascending: false })

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'referral codes GET failed')
      return NextResponse.json({ error: 'Failed to fetch referral codes' }, { status: 500 })
    }

    return NextResponse.json({ data: data ?? [] })
  } catch (err) {
    logger.error({ err }, 'referral codes GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

