input.content:
'use client'

import { useState, useTransition } from 'react'
import { Plus, MapPin } from 'lucide-react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { LocationCard } from './LocationCard'
import { EmptyState } from '@/components/shared/EmptyState'
import { KpiCard } from '@/components/shared/KpiCard'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import type { LocationStatus, MultiLocationOverview } from '@/lib/supabase/types'
import { formatCurrency } from '@/lib/utils'

interface LocationRow {
  id: string
  name: string
  address: string | null
  city: string | null
  state: string | null
  status: LocationStatus
  is_primary: boolean
  manager: { full_name: string | null } | null
  artist_count: number
  bookings_this_month: number
  opening_hours_summary: string | null
}

interface LocationsGridProps {
  locations: LocationRow[]
  overview: MultiLocationOverview | null
  canManage: boolean
}

export function LocationsGrid({ locations, overview, canManage }: LocationsGridProps) {
  const router = useRouter()
  const [, startTransition] = useTransition()
  const [deleteTarget, setDeleteTarget] = useState<{ id: string; name: string } | null>(null)
  const [isDeleting, setIsDeleting] = useState(false)

  function handleDeleteRequest(id: string, name: string) {
    setDeleteTarget({ id, name })
  }

  async function confirmDelete() {
    if (!deleteTarget) return
    setIsDeleting(true)
    try {
      const res = await fetch(`/api/locations/${deleteTarget.id}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Delete failed')
      toast.success(`${deleteTarget.name} deleted`)
      startTransition(() => router.refresh())
    } catch {
      toast.error('Failed to delete location')
    } finally {
      setIsDeleting(false)
      setDeleteTarget(null)
    }
  }

  return (
    <div className="space-y-6">
      {/* Overview KPI cards */}
      {overview && locations.length > 1 && (
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
          <KpiCard
            label="Total locations"
            value={String(locations.length)}
            icon={MapPin}
          />
          <KpiCard
            label="Total artists"
            value={String(overview.total_artists)}
            icon={MapPin}
          />
          <KpiCard
            label="Bookings (month)"
            value={String(overview.total_bookings)}
            icon={MapPin}
          />
          <KpiCard
            label="Revenue (month)"
            value={formatCurrency(overview.total_revenue_cents)}
            icon={MapPin}
          />
        </div>
      )}

      {/* Grid header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-base font-medium">
            {locations.length > 0 ? `${locations.length} location${locations.length !== 1 ? 's' : ''}` : 'Locations'}
          </h2>
        </div>
        {canManage && (
          <Button size="sm" render={<Link href="/locations/new" />}>
            <Plus className="mr-1.5 h-4 w-4" />
            Add location
          </Button>
        )}
      </div>

      {/* Empty state */}
      {locations.length === 0 ? (
        <EmptyState
          icon={MapPin}
          title="No locations yet"
          description="Add your first location to manage multiple studios."
          cta={canManage ? { label: 'Add location', href: '/locations/new' } : undefined}
        />
      ) : (
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {locations.map((loc) => (
            <LocationCard
              key={loc.id}
              id={loc.id}
              name={loc.name}
              address={loc.address}
              city={loc.city}
              state={loc.state}
              status={loc.status}
              managerName={loc.manager?.full_name ?? null}
              artistCount={loc.artist_count}
              bookingsThisMonth={loc.bookings_this_month}
              openingHoursSummary={loc.opening_hours_summary}
              isPrimary={loc.is_primary}
              canManage={canManage}
              onDelete={handleDeleteRequest}
            />
          ))}
        </div>
      )}

      {/* Delete confirmation */}
      <AlertDialog open={!!deleteTarget} onOpenChange={(open) => !open && setDeleteTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete location?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete <strong>{deleteTarget?.name}</strong>. Artist assignments
              and service overrides for this location will also be removed. Existing bookings are
              not affected.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isDeleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={confirmDelete}
              disabled={isDeleting}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {isDeleting ? 'Deleting...' : 'Delete'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { UserCircle, Star, Trash2, Plus } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Badge } from '@/components/ui/badge'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { EmptyState } from '@/components/shared/EmptyState'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'

interface AssignedArtist {
  id: string
  is_primary: boolean
  artist: {
    id: string
    display_name: string
    avatar_url: string | null
    status: string
  } | null
}

interface StudioArtist {
  id: string
  display_name: string
  avatar_url: string | null
}

interface ArtistAssignmentsProps {
  locationId: string
  locationName: string
  assignments: AssignedArtist[]
  allArtists: StudioArtist[]
  canManage: boolean
}

export function ArtistAssignments({
  locationId,
  locationName,
  assignments,
  allArtists,
  canManage,
}: ArtistAssignmentsProps) {
  const router = useRouter()
  const [, startTransition] = useTransition()
  const [selectedArtistId, setSelectedArtistId] = useState<string>('')
  const [isAssigning, setIsAssigning] = useState(false)
  const [removeTarget, setRemoveTarget] = useState<{ id: string; name: string } | null>(null)
  const [isRemoving, setIsRemoving] = useState(false)

  const assignedIds = new Set(
    assignments.map((a) => a.artist?.id).filter((id): id is string => Boolean(id))
  )
  const availableArtists = allArtists.filter((a) => !assignedIds.has(a.id))

  async function handleAssign() {
    if (!selectedArtistId) return
    setIsAssigning(true)
    try {
      const res = await fetch(`/api/locations/${locationId}/artists`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ artist_id: selectedArtistId, is_primary: assignments.length === 0 }),
      })
      if (!res.ok) throw new Error('Assign failed')
      toast.success('Artist assigned to location')
      setSelectedArtistId('')
      startTransition(() => router.refresh())
    } catch {
      toast.error('Failed to assign artist')
    } finally {
      setIsAssigning(false)
    }
  }

  async function handleRemove() {
    if (!removeTarget) return
    setIsRemoving(true)
    try {
      const res = await fetch(`/api/locations/${locationId}/artists`, {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ artist_id: removeTarget.id }),
      })
      if (!res.ok) throw new Error('Remove failed')
      toast.success(`${removeTarget.name} removed from ${locationName}`)
      startTransition(() => router.refresh())
    } catch {
      toast.error('Failed to remove artist')
    } finally {
      setIsRemoving(false)
      setRemoveTarget(null)
    }
  }

  return (
    <>
      <Card className="shadow-card">
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="text-sm font-medium">Artists at this location</CardTitle>
            {canManage && availableArtists.length > 0 && (
              <div className="flex items-center gap-2">
                <Select value={selectedArtistId} onValueChange={setSelectedArtistId}>
                  <SelectTrigger className="h-8 w-40 text-xs">
                    <SelectValue placeholder="Select artist" />
                  </SelectTrigger>
                  <SelectContent>
                    {availableArtists.map((a) => (
                      <SelectItem key={a.id} value={a.id} className="text-xs">
                        {a.display_name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <Button
                  size="sm"
                  className="h-8"
                  disabled={!selectedArtistId || isAssigning}
                  onClick={handleAssign}
                >
                  <Plus className="mr-1 h-3.5 w-3.5" />
                  Assign
                </Button>
              </div>
            )}
          </div>
        </CardHeader>
        <CardContent>
          {assignments.length === 0 ? (
            <EmptyState
              icon={UserCircle}
              title="No artists assigned"
              description="Assign artists to this location to filter bookings and calendar."
            />
          ) : (
            <ul className="space-y-2">
              {assignments.map((a) => {
                if (!a.artist) return null
                const initials = a.artist.display_name
                  .split(' ')
                  .map((n) => n[0])
                  .join('')
                  .toUpperCase()
                  .slice(0, 2)
                return (
                  <li key={a.id} className="flex items-center justify-between gap-3 rounded-lg border border-border px-3 py-2">
                    <div className="flex items-center gap-2.5 min-w-0">
                      <Avatar className="h-7 w-7">
                        <AvatarImage src={a.artist.avatar_url ?? undefined} alt={a.artist.display_name} />
                        <AvatarFallback className="text-[10px]">{initials}</AvatarFallback>
                      </Avatar>
                      <span className="text-sm font-medium truncate">{a.artist.display_name}</span>
                      {a.is_primary && (
                        <Badge variant="outline" className="h-5 text-[10px] gap-0.5 text-amber-600 border-amber-300 bg-amber-50">
                          <Star className="h-2.5 w-2.5 fill-current" />
                          Primary
                        </Badge>
                      )}
                    </div>
                    {canManage && (
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-7 w-7 text-muted-foreground hover:text-destructive shrink-0"
                        onClick={() => setRemoveTarget({ id: a.artist!.id, name: a.artist!.display_name })}
                        aria-label={`Remove ${a.artist.display_name}`}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    )}
                  </li>
                )
              })}
            </ul>
          )}
        </CardContent>
      </Card>

      <AlertDialog open={!!removeTarget} onOpenChange={(open) => !open && setRemoveTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Remove artist?</AlertDialogTitle>
            <AlertDialogDescription>
              Remove <strong>{removeTarget?.name}</strong> from{' '}
              <strong>{locationName}</strong>? This won&apos;t affect existing bookings.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isRemoving}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleRemove}
              disabled={isRemoving}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {isRemoving ? 'Removing...' : 'Remove'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { Wrench, Check, X } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Switch } from '@/components/ui/switch'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { EmptyState } from '@/components/shared/EmptyState'
import { formatCurrency } from '@/lib/utils'

interface ServiceWithOverride {
  service_id: string
  service_name: string
  service_duration_min: number
  service_base_price_cents: number
  service_color: string | null
  is_available: boolean
  price_override_cents: number | null
  duration_override_min: number | null
}

interface ServiceOverridesProps {
  locationId: string
  services: ServiceWithOverride[]
  canManage: boolean
}

export function ServiceOverrides({ locationId, services, canManage }: ServiceOverridesProps) {
  const router = useRouter()
  const [, startTransition] = useTransition()
  const [saving, setSaving] = useState<string | null>(null)

  async function handleUpdate(
    serviceId: string,
    update: { is_available?: boolean; price_override_cents?: number | null; duration_override_min?: number | null }
  ) {
    const current = services.find((s) => s.service_id === serviceId)
    if (!current) return

    setSaving(serviceId)
    try {
      const res = await fetch(`/api/locations/${locationId}/services`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          service_id: serviceId,
          is_available: update.is_available ?? current.is_available,
          price_override_cents: update.price_override_cents ?? current.price_override_cents,
          duration_override_min: update.duration_override_min ?? current.duration_override_min,
        }),
      })
      if (!res.ok) throw new Error('Update failed')
      toast.success('Service override updated')
      startTransition(() => router.refresh())
    } catch {
      toast.error('Failed to update service override')
    } finally {
      setSaving(null)
    }
  }

  if (services.length === 0) {
    return (
      <Card className="shadow-card">
        <CardContent className="pt-6">
          <EmptyState
            icon={Wrench}
            title="No services"
            description="Add services to the studio first, then override availability and pricing per location."
          />
        </CardContent>
      </Card>
    )
  }

  return (
    <Card className="shadow-card">
      <CardHeader>
        <CardTitle className="text-sm font-medium">Service overrides</CardTitle>
        <p className="text-xs text-muted-foreground mt-0.5">
          Toggle availability and override pricing or duration for this location.
        </p>
      </CardHeader>
      <CardContent>
        <div className="space-y-0">
          {services.map((svc, idx) => (
            <div
              key={svc.service_id}
              className={`flex items-start gap-4 py-3 ${idx > 0 ? 'border-t border-border' : ''}`}
            >
              {/* Availability toggle */}
              <div className="flex items-center gap-2 pt-0.5">
                <Switch
                  id={`avail-${svc.service_id}`}
                  checked={svc.is_available}
                  disabled={!canManage || saving === svc.service_id}
                  onCheckedChange={(checked) => handleUpdate(svc.service_id, { is_available: checked })}
                  aria-label={`Toggle ${svc.service_name} availability`}
                />
              </div>

              {/* Service info */}
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                  {svc.service_color && (
                    <span
                      className="h-2.5 w-2.5 rounded-full shrink-0"
                      style={{ backgroundColor: svc.service_color }}
                      aria-hidden="true"
                    />
                  )}
                  <span className={`text-sm font-medium ${!svc.is_available ? 'text-muted-foreground line-through' : ''}`}>
                    {svc.service_name}
                  </span>
                  {svc.is_available ? (
                    <Check className="h-3.5 w-3.5 text-green-600" aria-hidden="true" />
                  ) : (
                    <X className="h-3.5 w-3.5 text-muted-foreground" aria-hidden="true" />
                  )}
                </div>
                <p className="mt-0.5 text-xs text-muted-foreground">
                  Base: {formatCurrency(svc.service_base_price_cents)} &bull; {svc.service_duration_min} min
                </p>
              </div>

              {/* Override fields */}
              {canManage && svc.is_available && (
                <div className="flex items-center gap-3 shrink-0">
                  <div className="space-y-1">
                    <Label htmlFor={`price-${svc.service_id}`} className="text-[11px] text-muted-foreground">
                      Price override ($)
                    </Label>
                    <Input
                      id={`price-${svc.service_id}`}
                      type="number"
                      min="0"
                      step="0.01"
                      className="h-7 w-24 text-xs"
                      placeholder={String(svc.service_base_price_cents / 100)}
                      defaultValue={svc.price_override_cents ? svc.price_override_cents / 100 : ''}
                      onBlur={(e) => {
                        const val = e.target.value ? Math.round(parseFloat(e.target.value) * 100) : null
                        handleUpdate(svc.service_id, { price_override_cents: val })
                      }}
                      disabled={saving === svc.service_id}
                    />
                  </div>
                  <div className="space-y-1">
                    <Label htmlFor={`dur-${svc.service_id}`} className="text-[11px] text-muted-foreground">
                      Duration (min)
                    </Label>
                    <Input
                      id={`dur-${svc.service_id}`}
                      type="number"
                      min="5"
                      max="480"
                      className="h-7 w-20 text-xs"
                      placeholder={String(svc.service_duration_min)}
                      defaultValue={svc.duration_override_min ?? ''}
                      onBlur={(e) => {
                        const val = e.target.value ? parseInt(e.target.value, 10) : null
                        handleUpdate(svc.service_id, { duration_override_min: val })
                      }}
                      disabled={saving === svc.service_id}
                    />
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      </CardContent>
    </Card>
  )
}

import { Users, CalendarDays, DollarSign, Zap } from 'lucide-react'
import { KpiCard } from '@/components/shared/KpiCard'
import { formatCurrency } from '@/lib/utils'
import type { LocationDashboardData } from '@/lib/supabase/types'

interface LocationDashboardProps {
  data: LocationDashboardData
  currency?: string
}

export function LocationDashboard({ data, currency = 'USD' }: LocationDashboardProps) {
  const revenueChange =
    data.revenue_last_month_cents > 0
      ? Math.round(
          ((data.revenue_this_month_cents - data.revenue_last_month_cents) /
            data.revenue_last_month_cents) *
            100
        )
      : null

  return (
    <div className="grid grid-cols-2 gap-3 sm:grid-cols-2 lg:grid-cols-4">
      <KpiCard
        label="Artists"
        value={String(data.artist_count)}
        icon={Users}
      />
      <KpiCard
        label="Bookings (month)"
        value={String(data.bookings_this_month)}
        icon={CalendarDays}
      />
      <KpiCard
        label="Revenue (month)"
        value={formatCurrency(data.revenue_this_month_cents, currency)}
        icon={DollarSign}
        change={revenueChange ?? undefined}
      />
      <KpiCard
        label="Upcoming (7 days)"
        value={String(data.upcoming_7d)}
        icon={Zap}
      />
    </div>
  )
}

'use client'

import { MapPin } from 'lucide-react'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'

interface LocationOption {
  id: string
  name: string
}

interface LocationPickerProps {
  locations: LocationOption[]
  value: string | null
  onChange: (locationId: string | null) => void
  placeholder?: string
  className?: string
}

export function LocationPicker({
  locations,
  value,
  onChange,
  placeholder = 'All locations',
  className,
}: LocationPickerProps) {
  if (locations.length === 0) return null

  return (
    <Select
      value={value ?? 'all'}
      onValueChange={(v) => onChange(v === 'all' ? null : v)}
    >
      <SelectTrigger className={className}>
        <MapPin className="mr-1.5 h-3.5 w-3.5 text-muted-foreground" aria-hidden="true" />
        <SelectValue placeholder={placeholder} />
      </SelectTrigger>
      <SelectContent>
        <SelectItem value="all">{placeholder}</SelectItem>
        {locations.map((loc) => (
          <SelectItem key={loc.id} value={loc.id}>
            {loc.name}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  )
}

import { CheckCircle2, Clock, XCircle, AlertCircle } from 'lucide-react'

type VerificationStatus = 'pending' | 'verified' | 'failed' | 'unset'

interface DomainStatusProps {
  status: VerificationStatus
  domain?: string | null
  verifiedAt?: string | null
  error?: string | null
}

const CONFIG: Record<VerificationStatus, { icon: typeof CheckCircle2; label: string; className: string }> = {
  verified: {
    icon: CheckCircle2,
    label: 'Verified',
    className: 'text-[oklch(58%_0.18_145)]',
  },
  pending: {
    icon: Clock,
    label: 'Pending DNS check',
    className: 'text-[oklch(70%_0.16_72)]',
  },
  failed: {
    icon: XCircle,
    label: 'Verification failed',
    className: 'text-destructive',
  },
  unset: {
    icon: AlertCircle,
    label: 'No domain configured',
    className: 'text-muted-foreground',
  },
}

export function DomainStatus({ status, domain, verifiedAt, error }: DomainStatusProps) {
  const config = CONFIG[status]
  const Icon = config.icon

  return (
    <div className="flex items-start gap-2">
      <Icon className={`mt-0.5 h-4 w-4 shrink-0 ${config.className}`} aria-hidden="true" />
      <div className="space-y-0.5">
        <p className={`text-sm font-medium ${config.className}`}>{config.label}</p>
        {domain && status !== 'unset' && (
          <p className="text-xs text-muted-foreground font-mono">{domain}</p>
        )}
        {verifiedAt && status === 'verified' && (
          <p className="text-xs text-muted-foreground">
            Verified {new Date(verifiedAt).toLocaleDateString()}
          </p>
        )}
        {error && status === 'failed' && (
          <p className="text-xs text-destructive">{error}</p>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { RefreshCw, Copy } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card'
import { DomainStatus } from './DomainStatus'

const CNAME_TARGET = 'proxy.inkos.app'

interface DomainVerificationProps {
  currentDomain: string | null
  isVerified: boolean
  verifiedAt: string | null
  verificationError: string | null
  canEdit: boolean
}

export function DomainVerification({
  currentDomain,
  isVerified,
  verifiedAt,
  verificationError,
  canEdit,
}: DomainVerificationProps) {
  const router = useRouter()
  const [, startTransition] = useTransition()
  const [domain, setDomain] = useState(currentDomain ?? '')
  const [isSaving, setIsSaving] = useState(false)
  const [isVerifying, setIsVerifying] = useState(false)
  const [copied, setCopied] = useState(false)

  const status = !currentDomain
    ? 'unset'
    : isVerified
    ? 'verified'
    : verificationError
    ? 'failed'
    : 'pending'

  async function handleSaveDomain() {
    setIsSaving(true)
    try {
      const res = await fetch('/api/branding', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ custom_domain: domain || null }),
      })
      if (!res.ok) throw new Error()
      toast.success('Domain saved')
      startTransition(() => router.refresh())
    } catch {
      toast.error('Failed to save domain')
    } finally {
      setIsSaving(false)
    }
  }

  async function handleVerify() {
    setIsVerifying(true)
    try {
      const res = await fetch('/api/branding/domain/verify', { method: 'POST' })
      const json: unknown = await res.json()
      if (!res.ok) throw new Error()
      const data = json && typeof json === 'object' && 'data' in json ? (json as { data: { verified: boolean; error: string | null } }).data : null
      if (data?.verified) {
        toast.success('Domain verified successfully!')
      } else {
        toast.error(data?.error ?? 'Verification failed — check your DNS settings')
      }
      startTransition(() => router.refresh())
    } catch {
      toast.error('Verification check failed')
    } finally {
      setIsVerifying(false)
    }
  }

  async function handleCopy() {
    await navigator.clipboard.writeText(CNAME_TARGET)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  return (
    <Card className="shadow-card">
      <CardHeader>
        <CardTitle className="text-sm font-medium">Custom domain</CardTitle>
        <CardDescription className="text-xs">
          Point a subdomain (e.g. book.mystudio.com) to InkOS via a CNAME record.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {canEdit && (
          <div className="space-y-1.5">
            <Label htmlFor="custom-domain">Your subdomain</Label>
            <div className="flex gap-2">
              <Input
                id="custom-domain"
                placeholder="book.mystudio.com"
                value={domain}
                onChange={(e) => setDomain(e.target.value)}
                className="font-mono text-sm"
              />
              <Button
                variant="outline"
                disabled={isSaving || domain === (currentDomain ?? '')}
                onClick={handleSaveDomain}
              >
                {isSaving ? 'Saving...' : 'Save'}
              </Button>
            </div>
          </div>
        )}

        {currentDomain && (
          <>
            <div className="rounded-lg border border-border bg-muted/40 p-3 space-y-2">
              <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">DNS CNAME record</p>
              <div className="grid grid-cols-2 gap-2 text-xs">
                <div>
                  <p className="text-muted-foreground">Type</p>
                  <p className="font-mono font-medium">CNAME</p>
                </div>
                <div>
                  <p className="text-muted-foreground">Name / Host</p>
                  <p className="font-mono font-medium truncate">{currentDomain.split('.')[0]}</p>
                </div>
                <div className="col-span-2">
                  <p className="text-muted-foreground">Value / Points to</p>
                  <div className="flex items-center gap-2">
                    <p className="font-mono font-medium">{CNAME_TARGET}</p>
                    <button
                      type="button"
                      onClick={handleCopy}
                      className="text-muted-foreground hover:text-foreground transition-colors"
                      aria-label="Copy CNAME value"
                    >
                      <Copy className="h-3.5 w-3.5" />
                    </button>
                    {copied && <span className="text-xs text-green-600">Copied!</span>}
                  </div>
                </div>
              </div>
            </div>

            <div className="flex items-center justify-between">
              <DomainStatus
                status={status}
                domain={currentDomain}
                verifiedAt={verifiedAt}
                error={verificationError}
              />
              {!isVerified && canEdit && (
                <Button
                  variant="outline"
                  size="sm"
                  onClick={handleVerify}
                  disabled={isVerifying}
                >
                  <RefreshCw className={`mr-1.5 h-3.5 w-3.5 ${isVerifying ? 'animate-spin' : ''}`} />
                  {isVerifying ? 'Checking...' : 'Verify DNS'}
                </Button>
              )}
            </div>
          </>
        )}
      </CardContent>
    </Card>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { Eye, EyeOff } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Switch } from '@/components/ui/switch'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'

interface BrandingSettingsProps {
  whiteLabelEnabled: boolean
  poweredByHidden: boolean
  customFaviconUrl: string | null
  customEmailFromName: string | null
  customEmailReplyTo: string | null
  canEdit: boolean
}

export function BrandingSettings({
  whiteLabelEnabled,
  poweredByHidden,
  customFaviconUrl,
  customEmailFromName,
  customEmailReplyTo,
  canEdit,
}: BrandingSettingsProps) {
  const router = useRouter()
  const [, startTransition] = useTransition()
  const [isSaving, setIsSaving] = useState(false)

  const [form, setForm] = useState({
    white_label_enabled: whiteLabelEnabled,
    powered_by_hidden: poweredByHidden,
    custom_favicon_url: customFaviconUrl ?? '',
    custom_email_from_name: customEmailFromName ?? '',
    custom_email_reply_to: customEmailReplyTo ?? '',
  })

  function update<K extends keyof typeof form>(key: K, value: typeof form[K]) {
    setForm((prev) => ({ ...prev, [key]: value }))
  }

  async function handleSave() {
    setIsSaving(true)
    try {
      const res = await fetch('/api/branding', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          white_label_enabled: form.white_label_enabled,
          powered_by_hidden: form.powered_by_hidden,
          custom_favicon_url: form.custom_favicon_url || null,
          custom_email_from_name: form.custom_email_from_name || null,
          custom_email_reply_to: form.custom_email_reply_to || null,
        }),
      })
      if (!res.ok) throw new Error()
      toast.success('Branding settings saved')
      startTransition(() => router.refresh())
    } catch {
      toast.error('Failed to save branding settings')
    } finally {
      setIsSaving(false)
    }
  }

  return (
    <Card className="shadow-card">
      <CardHeader>
        <CardTitle className="text-sm font-medium">White-label settings</CardTitle>
        <CardDescription className="text-xs">
          Remove InkOS branding from client-facing pages and emails.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-5">
        {/* Enable white-label */}
        <div className="flex items-center justify-between gap-4">
          <div>
            <p className="text-sm font-medium">Enable white-label</p>
            <p className="text-xs text-muted-foreground">Apply custom branding to all public pages.</p>
          </div>
          <Switch
            checked={form.white_label_enabled}
            onCheckedChange={(v) => update('white_label_enabled', v)}
            disabled={!canEdit}
            aria-label="Enable white-label"
          />
        </div>

        {/* Hide powered by */}
        <div className="flex items-center justify-between gap-4">
          <div className="flex items-center gap-2">
            {form.powered_by_hidden ? (
              <EyeOff className="h-4 w-4 text-muted-foreground" aria-hidden="true" />
            ) : (
              <Eye className="h-4 w-4 text-muted-foreground" aria-hidden="true" />
            )}
            <div>
              <p className="text-sm font-medium">Hide &quot;Powered by InkOS&quot;</p>
              <p className="text-xs text-muted-foreground">Remove the footer attribution from booking pages.</p>
            </div>
          </div>
          <Switch
            checked={form.powered_by_hidden}
            onCheckedChange={(v) => update('powered_by_hidden', v)}
            disabled={!canEdit || !form.white_label_enabled}
            aria-label="Hide Powered by InkOS"
          />
        </div>

        <div className="border-t border-border pt-4 space-y-4">
          {/* Favicon */}
          <div className="space-y-1.5">
            <Label htmlFor="favicon-url">Custom favicon URL</Label>
            <Input
              id="favicon-url"
              type="url"
              placeholder="https://cdn.mystudio.com/favicon.ico"
              value={form.custom_favicon_url}
              onChange={(e) => update('custom_favicon_url', e.target.value)}
              disabled={!canEdit}
            />
            <p className="text-xs text-muted-foreground">16x16 or 32x32 .ico, .png, or .svg.</p>
          </div>

          {/* Email from name */}
          <div className="space-y-1.5">
            <Label htmlFor="email-from-name">Email from name</Label>
            <Input
              id="email-from-name"
              placeholder="My Studio"
              value={form.custom_email_from_name}
              onChange={(e) => update('custom_email_from_name', e.target.value)}
              disabled={!canEdit}
            />
            <p className="text-xs text-muted-foreground">Appears as the sender name in all studio emails.</p>
          </div>

          {/* Email reply-to */}
          <div className="space-y-1.5">
            <Label htmlFor="email-reply-to">Email reply-to</Label>
            <Input
              id="email-reply-to"
              type="email"
              placeholder="hello@mystudio.com"
              value={form.custom_email_reply_to}
              onChange={(e) => update('custom_email_reply_to', e.target.value)}
              disabled={!canEdit}
            />
          </div>
        </div>

        {canEdit && (
          <div className="flex justify-end pt-1">
            <Button onClick={handleSave} disabled={isSaving} size="sm">
              {isSaving ? 'Saving...' : 'Save settings'}
            </Button>
          </div>
        )}
      </CardContent>
    </Card>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { Plus, Trash2, Users } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Badge } from '@/components/ui/badge'
import type { AudienceFilter } from '@/lib/supabase/types'

type ConditionType = 'tags' | 'last_visit_days' | 'min_spent_cents' | 'max_spent_cents' | 'location_ids'

interface Condition {
  id: string
  type: ConditionType
  value: string
}

const CONDITION_LABELS: Record<ConditionType, string> = {
  tags: 'Has tag',
  last_visit_days: 'Last visited (days ago)',
  min_spent_cents: 'Total spent min ($)',
  max_spent_cents: 'Total spent max ($)',
  location_ids: 'At location',
}

interface AudienceFilterBuilderProps {
  value: AudienceFilter
  onChange: (filter: AudienceFilter) => void
  studioId: string
  locationOptions?: Array<{ id: string; name: string }>
}

function buildFilter(conditions: Condition[]): AudienceFilter {
  const filter: AudienceFilter = {}
  const tags: string[] = []
  const locationIds: string[] = []

  for (const c of conditions) {
    if (!c.value) continue
    switch (c.type) {
      case 'tags':
        tags.push(c.value)
        break
      case 'last_visit_days':
        filter.last_visit_days = parseInt(c.value, 10) || undefined
        break
      case 'min_spent_cents':
        filter.min_spent_cents = Math.round(parseFloat(c.value) * 100) || undefined
        break
      case 'max_spent_cents':
        filter.max_spent_cents = Math.round(parseFloat(c.value) * 100) || undefined
        break
      case 'location_ids':
        locationIds.push(c.value)
        break
    }
  }

  if (tags.length > 0) filter.tags = tags
  if (locationIds.length > 0) filter.location_ids = locationIds
  return filter
}

export function AudienceFilterBuilder({
  value,
  onChange,
  studioId,
  locationOptions = [],
}: AudienceFilterBuilderProps) {
  const [conditions, setConditions] = useState<Condition[]>([])
  const [audienceCount, setAudienceCount] = useState<number | null>(null)
  const [isLoading, setIsLoading] = useState(false)

  const checkCount = useCallback(async (filter: AudienceFilter) => {
    setIsLoading(true)
    try {
      const res = await fetch('/api/marketing/campaigns/audience-count', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(filter),
      })
      if (!res.ok) return
      const json: unknown = await res.json()
      if (json && typeof json === 'object' && 'data' in json) {
        const data = (json as { data: { audience_count: number } }).data
        setAudienceCount(data.audience_count)
      }
    } catch {
      // non-blocking
    } finally {
      setIsLoading(false)
    }
  }, [])

  useEffect(() => {
    // Initialize conditions from value prop
    const initial: Condition[] = []
    const idGen = () => Math.random().toString(36).slice(2)
    if (value.tags) {
      for (const tag of value.tags) {
        initial.push({ id: idGen(), type: 'tags', value: tag })
      }
    }
    if (value.last_visit_days !== undefined) {
      initial.push({ id: idGen(), type: 'last_visit_days', value: String(value.last_visit_days) })
    }
    if (value.min_spent_cents !== undefined) {
      initial.push({ id: idGen(), type: 'min_spent_cents', value: String(value.min_spent_cents / 100) })
    }
    if (value.max_spent_cents !== undefined) {
      initial.push({ id: idGen(), type: 'max_spent_cents', value: String(value.max_spent_cents / 100) })
    }
    if (value.location_ids) {
      for (const id of value.location_ids) {
        initial.push({ id: idGen(), type: 'location_ids', value: id })
      }
    }
    setConditions(initial)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  function addCondition() {
    setConditions((prev) => [
      ...prev,
      { id: Math.random().toString(36).slice(2), type: 'tags', value: '' },
    ])
  }

  function removeCondition(id: string) {
    const next = conditions.filter((c) => c.id !== id)
    setConditions(next)
    const filter = buildFilter(next)
    onChange(filter)
    if (next.length > 0) checkCount(filter)
    else { setAudienceCount(null) }
  }

  function updateCondition(id: string, field: 'type' | 'value', val: string) {
    const next = conditions.map((c) => c.id === id ? { ...c, [field]: val } : c)
    setConditions(next)
    const filter = buildFilter(next)
    onChange(filter)
    checkCount(filter)
  }

  void studioId // used for future server-side tag autocomplete

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <Label className="text-sm font-medium">Audience conditions (AND logic)</Label>
        <Button type="button" variant="outline" size="sm" onClick={addCondition}>
          <Plus className="mr-1.5 h-3.5 w-3.5" />
          Add condition
        </Button>
      </div>

      {conditions.length === 0 ? (
        <p className="text-xs text-muted-foreground">No conditions — campaign will target all clients.</p>
      ) : (
        <div className="space-y-2">
          {conditions.map((cond, idx) => (
            <div key={cond.id} className="flex items-center gap-2">
              {idx > 0 && (
                <span className="text-xs text-muted-foreground w-6 text-center shrink-0">AND</span>
              )}
              {idx === 0 && <span className="text-xs text-muted-foreground w-6 shrink-0">If</span>}

              <Select
                value={cond.type}
                onValueChange={(v) => updateCondition(cond.id, 'type', v)}
              >
                <SelectTrigger className="h-8 w-44 text-xs">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {(Object.entries(CONDITION_LABELS) as [ConditionType, string][]).map(([val, label]) => (
                    <SelectItem key={val} value={val} className="text-xs">{label}</SelectItem>
                  ))}
                </SelectContent>
              </Select>

              {cond.type === 'location_ids' ? (
                <Select
                  value={cond.value}
                  onValueChange={(v) => updateCondition(cond.id, 'value', v)}
                >
                  <SelectTrigger className="h-8 flex-1 text-xs">
                    <SelectValue placeholder="Select location" />
                  </SelectTrigger>
                  <SelectContent>
                    {locationOptions.map((loc) => (
                      <SelectItem key={loc.id} value={loc.id} className="text-xs">{loc.name}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              ) : (
                <Input
                  className="h-8 flex-1 text-xs"
                  placeholder={
                    cond.type === 'tags' ? 'Tag name' :
                    cond.type === 'last_visit_days' ? 'e.g. 90' :
                    'e.g. 100'
                  }
                  value={cond.value}
                  onChange={(e) => updateCondition(cond.id, 'value', e.target.value)}
                />
              )}

              <button
                type="button"
                onClick={() => removeCondition(cond.id)}
                className="text-muted-foreground hover:text-destructive transition-colors"
                aria-label="Remove condition"
              >
                <Trash2 className="h-4 w-4" />
              </button>
            </div>
          ))}
        </div>
      )}

      {/* Audience count preview */}
      <div className="flex items-center gap-2">
        <Users className="h-4 w-4 text-muted-foreground" aria-hidden="true" />
        {isLoading ? (
          <span className="text-xs text-muted-foreground">Calculating...</span>
        ) : audienceCount !== null ? (
          <span className="text-xs text-muted-foreground">
            Matches{' '}
            <Badge variant="outline" className="text-[11px] px-1.5 py-0">
              {audienceCount.toLocaleString()}
            </Badge>{' '}
            client{audienceCount !== 1 ? 's' : ''}
          </span>
        ) : conditions.length === 0 ? (
          <span className="text-xs text-muted-foreground">All clients</span>
        ) : null}
      </div>
    </div>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { toast } from 'sonner'
import { Plus, Megaphone } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { CampaignCard } from './CampaignCard'
import { EmptyState } from '@/components/shared/EmptyState'
import { PageHeader } from '@/components/shared/PageHeader'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import type { CampaignType, CampaignStatus, CampaignChannel } from '@/lib/supabase/types'

interface Campaign {
  id: string
  name: string
  type: CampaignType
  channel: CampaignChannel
  status: CampaignStatus
  sent_count: number
  open_count: number
  click_count: number
  scheduled_at: string | null
  sent_at: string | null
}

interface CampaignsHubProps {
  campaigns: Campaign[]
  canManage: boolean
}

export function CampaignsHub({ campaigns, canManage }: CampaignsHubProps) {
  const router = useRouter()
  const [, startTransition] = useTransition()
  const [deleteTarget, setDeleteTarget] = useState<{ id: string; name: string } | null>(null)
  const [isDeleting, setIsDeleting] = useState(false)
  const [sendTarget, setSendTarget] = useState<{ id: string; name: string } | null>(null)
  const [isSending, setIsSending] = useState(false)

  async function confirmDelete() {
    if (!deleteTarget) return
    setIsDeleting(true)
    try {
      const res = await fetch(`/api/marketing/campaigns/${deleteTarget.id}`, { method: 'DELETE' })
      if (!res.ok) throw new Error()
      toast.success(`Campaign deleted`)
      startTransition(() => router.refresh())
    } catch {
      toast.error('Failed to delete campaign')
    } finally {
      setIsDeleting(false)
      setDeleteTarget(null)
    }
  }

  async function confirmSend() {
    if (!sendTarget) return
    setIsSending(true)
    try {
      const res = await fetch(`/api/marketing/campaigns/${sendTarget.id}/send`, { method: 'POST' })
      if (!res.ok) throw new Error()
      toast.success(`${sendTarget.name} queued to send`)
      startTransition(() => router.refresh())
    } catch {
      toast.error('Failed to send campaign')
    } finally {
      setIsSending(false)
      setSendTarget(null)
    }
  }

  async function handleTogglePause(id: string, currentStatus: CampaignStatus) {
    const newStatus = currentStatus === 'active' ? 'paused' : 'active'
    try {
      const res = await fetch(`/api/marketing/campaigns/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus }),
      })
      if (!res.ok) throw new Error()
      toast.success(newStatus === 'paused' ? 'Campaign paused' : 'Campaign resumed')
      startTransition(() => router.refresh())
    } catch {
      toast.error('Failed to update campaign')
    }
  }

  return (
    <div className="space-y-6">
      <PageHeader
        title="Marketing campaigns"
        subtitle="Send automated and manual campaigns to your clients."
        right={
          canManage && (
            <Button size="sm" render={<Link href="/marketing/campaigns/new" />}>
              <Plus className="mr-1.5 h-4 w-4" />
              New campaign
            </Button>
          )
        }
      />

      {campaigns.length === 0 ? (
        <EmptyState
          icon={Megaphone}
          title="No campaigns yet"
          description="Create your first campaign to start engaging clients via email or SMS."
          cta={canManage ? { label: 'Create campaign', href: '/marketing/campaigns/new' } : undefined}
        />
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {campaigns.map((c) => (
            <CampaignCard
              key={c.id}
              id={c.id}
              name={c.name}
              type={c.type}
              channel={c.channel}
              status={c.status}
              sentCount={c.sent_count}
              openCount={c.open_count}
              clickCount={c.click_count}
              scheduledAt={c.scheduled_at}
              sentAt={c.sent_at}
              canManage={canManage}
              onSend={(id, name) => setSendTarget({ id, name })}
              onTogglePause={handleTogglePause}
              onDelete={(id, name) => setDeleteTarget({ id, name })}
            />
          ))}
        </div>
      )}

      {/* Delete dialog */}
      <AlertDialog open={!!deleteTarget} onOpenChange={(open) => !open && setDeleteTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete campaign?</AlertDialogTitle>
            <AlertDialogDescription>
              Permanently delete <strong>{deleteTarget?.name}</strong>? This cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isDeleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={confirmDelete}
              disabled={isDeleting}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {isDeleting ? 'Deleting...' : 'Delete'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Send dialog */}
      <AlertDialog open={!!sendTarget} onOpenChange={(open) => !open && setSendTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Send now?</AlertDialogTitle>
            <AlertDialogDescription>
              <strong>{sendTarget?.name}</strong> will be sent immediately to all matching clients.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isSending}>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={confirmSend} disabled={isSending}>
              {isSending ? 'Queueing...' : 'Send campaign'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { Gift, Copy, Check, Plus, Users } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { EmptyState } from '@/components/shared/EmptyState'
import { KpiCard } from '@/components/shared/KpiCard'

interface ReferralCodeRow {
  id: string
  code: string
  discount_type: 'percentage' | 'fixed'
  discount_value: number
  uses_count: number
  max_uses: number | null
  is_active: boolean
  client: { id: string; first_name: string; last_name: string; email: string } | null
}

interface ClientOption {
  id: string
  display: string
}

interface ReferralDashboardProps {
  codes: ReferralCodeRow[]
  totalReferrals: number
  totalRedemptions: number
  topReferrers: number
  clientOptions: ClientOption[]
  canManage: boolean
}

export function ReferralDashboard({
  codes,
  totalReferrals,
  totalRedemptions,
  topReferrers,
  clientOptions,
  canManage,
}: ReferralDashboardProps) {
  const router = useRouter()
  const [, startTransition] = useTransition()
  const [selectedClientId, setSelectedClientId] = useState<string>('')
  const [isGenerating, setIsGenerating] = useState(false)
  const [copied, setCopied] = useState<string | null>(null)

  async function handleGenerateCode() {
    if (!selectedClientId) return
    setIsGenerating(true)
    try {
      const res = await fetch('/api/marketing/referrals/codes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ client_id: selectedClientId }),
      })
      if (!res.ok) throw new Error()
      const json: unknown = await res.json()
      const data = json && typeof json === 'object' && 'data' in json
        ? (json as { data: { existing: boolean; code: string } }).data
        : null
      if (data?.existing) {
        toast.success(`Existing code: ${data.code}`)
      } else {
        toast.success('Referral code generated')
      }
      setSelectedClientId('')
      startTransition(() => router.refresh())
    } catch {
      toast.error('Failed to generate code')
    } finally {
      setIsGenerating(false)
    }
  }

  async function handleCopy(code: string) {
    await navigator.clipboard.writeText(code)
    setCopied(code)
    setTimeout(() => setCopied(null), 1500)
  }

  return (
    <div className="space-y-5">
      {/* KPIs */}
      <div className="grid grid-cols-3 gap-3">
        <KpiCard label="Total codes" value={String(totalReferrals)} icon={Gift} />
        <KpiCard label="Redemptions" value={String(totalRedemptions)} icon={Users} />
        <KpiCard label="Top referrers" value={String(topReferrers)} icon={Users} />
      </div>

      {/* Generate code */}
      {canManage && clientOptions.length > 0 && (
        <Card className="shadow-card">
          <CardHeader>
            <CardTitle className="text-sm font-medium">Generate referral code</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="flex items-center gap-2">
              <Select value={selectedClientId} onValueChange={setSelectedClientId}>
                <SelectTrigger className="flex-1">
                  <SelectValue placeholder="Select client" />
                </SelectTrigger>
                <SelectContent>
                  {clientOptions.map((c) => (
                    <SelectItem key={c.id} value={c.id}>{c.display}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Button
                size="sm"
                disabled={!selectedClientId || isGenerating}
                onClick={handleGenerateCode}
              >
                <Plus className="mr-1.5 h-3.5 w-3.5" />
                {isGenerating ? 'Generating...' : 'Generate'}
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Code list */}
      <Card className="shadow-card">
        <CardHeader>
          <CardTitle className="text-sm font-medium">Referral codes</CardTitle>
        </CardHeader>
        <CardContent>
          {codes.length === 0 ? (
            <EmptyState
              icon={Gift}
              title="No referral codes"
              description="Generate codes for clients to share with friends."
            />
          ) : (
            <ul className="space-y-2">
              {codes.map((code) => (
                <li key={code.id} className="flex items-center justify-between gap-3 rounded-lg border border-border px-3 py-2">
                  <div className="min-w-0">
                    <div className="flex items-center gap-2">
                      <code className="text-sm font-mono font-semibold">{code.code}</code>
                      <button
                        type="button"
                        onClick={() => handleCopy(code.code)}
                        className="text-muted-foreground hover:text-foreground transition-colors"
                        aria-label="Copy code"
                      >
                        {copied === code.code ? (
                          <Check className="h-3.5 w-3.5 text-green-600" />
                        ) : (
                          <Copy className="h-3.5 w-3.5" />
                        )}
                      </button>
                      {!code.is_active && (
                        <Badge variant="outline" className="text-[11px] text-muted-foreground">Inactive</Badge>
                      )}
                    </div>
                    {code.client && (
                      <p className="text-xs text-muted-foreground truncate">
                        {code.client.first_name} {code.client.last_name}
                      </p>
                    )}
                  </div>
                  <div className="text-right shrink-0">
                    <p className="text-xs font-medium">
                      {code.discount_type === 'percentage'
                        ? `${code.discount_value}% off`
                        : `$${code.discount_value} off`}
                    </p>
                    <p className="text-xs text-muted-foreground">
                      {code.uses_count}{code.max_uses ? `/${code.max_uses}` : ''} uses
                    </p>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { toast } from 'sonner'
import { Calendar, Loader2, Plug2, Unplug, RefreshCw } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Label } from '@/components/ui/label'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import type { CalendarSyncDirection } from '@/lib/supabase/types'

interface ArtistCalendarSync {
  id: string
  artistId: string
  artistName: string
  isActive: boolean
  syncDirection: CalendarSyncDirection
  provider: string
}

interface GoogleCalendarConnectProps {
  artistId: string
  artistName: string
  sync: ArtistCalendarSync | null
  onRefresh: () => void
}

export function GoogleCalendarConnect({
  artistId,
  artistName,
  sync,
  onRefresh,
}: GoogleCalendarConnectProps) {
  const [syncDirection, setSyncDirection] = useState<CalendarSyncDirection>('export')
  const [isConnecting, setIsConnecting] = useState(false)
  const [isSyncing, setIsSyncing] = useState(false)
  const [isDisconnecting, setIsDisconnecting] = useState(false)
  const [showDisconnect, setShowDisconnect] = useState(false)

  async function handleConnect() {
    setIsConnecting(true)
    try {
      const res = await fetch('/api/integrations/google-calendar/connect', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ artist_id: artistId, sync_direction: syncDirection }),
      })
      if (!res.ok) {
        const json: unknown = await res.json()
        const msg =
          typeof json === 'object' && json !== null && 'error' in json
            ? String((json as { error: unknown }).error)
            : 'Failed to initiate connection'
        toast.error(msg)
        return
      }
      const json: unknown = await res.json()
      if (
        json &&
        typeof json === 'object' &&
        'data' in json &&
        json.data &&
        typeof json.data === 'object' &&
        'auth_url' in json.data
      ) {
        window.location.href = (json.data as { auth_url: string }).auth_url
      }
    } catch {
      toast.error('Failed to initiate Google Calendar connection')
    } finally {
      setIsConnecting(false)
    }
  }

  async function handleSync() {
    setIsSyncing(true)
    try {
      const res = await fetch('/api/integrations/google-calendar/sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ artist_id: artistId }),
      })
      if (!res.ok) throw new Error()
      toast.success('Calendar sync queued')
    } catch {
      toast.error('Failed to queue sync')
    } finally {
      setIsSyncing(false)
    }
  }

  async function handleDisconnect() {
    setIsDisconnecting(true)
    try {
      const res = await fetch('/api/integrations/google-calendar/disconnect', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ artist_id: artistId }),
      })
      if (!res.ok) throw new Error()
      toast.success('Google Calendar disconnected')
      onRefresh()
    } catch {
      toast.error('Failed to disconnect')
    } finally {
      setIsDisconnecting(false)
      setShowDisconnect(false)
    }
  }

  const directionLabel: Record<CalendarSyncDirection, string> = {
    export: 'Export (InkOS → Google)',
    import: 'Import (Google → InkOS)',
    bidirectional: 'Two-way sync',
  }

  return (
    <div className="flex items-start justify-between gap-4">
      <div className="flex items-center gap-3 min-w-0">
        <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg border border-border bg-background">
          <Calendar className="h-4 w-4 text-muted-foreground" />
        </div>
        <div className="min-w-0">
          <p className="text-sm font-medium truncate">{artistName}</p>
          {sync?.isActive ? (
            <div className="flex items-center gap-2 mt-0.5">
              <Badge
                variant="outline"
                className="text-[11px] border-[oklch(52%_0.15_145/0.4)] text-[oklch(52%_0.15_145)]"
              >
                Connected
              </Badge>
              <span className="text-xs text-muted-foreground">
                {directionLabel[sync.syncDirection]}
              </span>
            </div>
          ) : (
            <p className="text-xs text-muted-foreground mt-0.5">Not connected</p>
          )}
        </div>
      </div>

      <div className="flex items-center gap-2 shrink-0">
        {sync?.isActive ? (
          <>
            <Button
              type="button"
              variant="outline"
              size="sm"
              disabled={isSyncing}
              onClick={handleSync}
            >
              {isSyncing ? (
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
              ) : (
                <RefreshCw className="h-3.5 w-3.5" />
              )}
              <span className="ml-1.5">Sync now</span>
            </Button>
            <Button
              type="button"
              variant="ghost"
              size="sm"
              className="text-muted-foreground hover:text-destructive"
              onClick={() => setShowDisconnect(true)}
            >
              <Unplug className="h-3.5 w-3.5" />
              <span className="ml-1.5">Disconnect</span>
            </Button>
          </>
        ) : (
          <div className="flex items-center gap-2">
            <div className="flex flex-col gap-1">
              <Label className="sr-only">Sync direction</Label>
              <Select
                value={syncDirection}
                onValueChange={(v) => setSyncDirection(v as CalendarSyncDirection)}
              >
                <SelectTrigger className="h-8 w-48 text-xs">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="export" className="text-xs">
                    Export to Google
                  </SelectItem>
                  <SelectItem value="import" className="text-xs">
                    Import from Google
                  </SelectItem>
                  <SelectItem value="bidirectional" className="text-xs">
                    Two-way sync
                  </SelectItem>
                </SelectContent>
              </Select>
            </div>
            <Button
              type="button"
              size="sm"
              disabled={isConnecting}
              onClick={handleConnect}
            >
              {isConnecting ? (
                <Loader2 className="mr-1.5 h-3.5 w-3.5 animate-spin" />
              ) : (
                <Plug2 className="mr-1.5 h-3.5 w-3.5" />
              )}
              Connect
            </Button>
          </div>
        )}
      </div>

      <AlertDialog open={showDisconnect} onOpenChange={setShowDisconnect}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Disconnect Google Calendar?</AlertDialogTitle>
            <AlertDialogDescription>
              Remove the Google Calendar connection for <strong>{artistName}</strong>. Their bookings will no longer sync.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isDisconnecting}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDisconnect}
              disabled={isDisconnecting}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {isDisconnecting ? 'Disconnecting...' : 'Disconnect'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { toast } from 'sonner'
import { Download, FileSpreadsheet, Loader2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Label } from '@/components/ui/label'

type ExportType = 'commissions' | 'payroll' | 'invoices'

export function QuickBooksExport() {
  const [exportType, setExportType] = useState<ExportType>('commissions')
  const [isExporting, setIsExporting] = useState(false)

  async function handleExport() {
    setIsExporting(true)
    try {
      const res = await fetch(`/api/integrations/quickbooks/export?type=${exportType}`)
      if (!res.ok) {
        const json: unknown = await res.json()
        const msg =
          typeof json === 'object' && json !== null && 'error' in json
            ? String((json as { error: unknown }).error)
            : 'Export failed'
        toast.error(msg)
        return
      }
      const blob = await res.blob()
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      const date = new Date().toISOString().split('T')[0]
      a.download = `inkos-${exportType}-${date}.csv`
      document.body.appendChild(a)
      a.click()
      document.body.removeChild(a)
      URL.revokeObjectURL(url)
      toast.success(`${exportType.charAt(0).toUpperCase() + exportType.slice(1)} exported`)
    } catch {
      toast.error('Export failed')
    } finally {
      setIsExporting(false)
    }
  }

  const exportLabels: Record<ExportType, string> = {
    commissions: 'Artist commissions',
    payroll: 'Payroll summary',
    invoices: 'Invoice ledger',
  }

  return (
    <div className="flex items-center justify-between gap-4">
      <div className="flex items-center gap-3">
        <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg border border-border bg-background">
          <FileSpreadsheet className="h-4 w-4 text-muted-foreground" />
        </div>
        <div>
          <p className="text-sm font-medium">QuickBooks CSV export</p>
          <p className="text-xs text-muted-foreground">
            Download QuickBooks-compatible data for import
          </p>
        </div>
      </div>

      <div className="flex items-center gap-2 shrink-0">
        <div className="flex flex-col gap-1">
          <Label className="sr-only">Export type</Label>
          <Select
            value={exportType}
            onValueChange={(v) => setExportType(v as ExportType)}
          >
            <SelectTrigger className="h-8 w-44 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {(Object.entries(exportLabels) as [ExportType, string][]).map(([val, label]) => (
                <SelectItem key={val} value={val} className="text-xs">
                  {label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <Button
          type="button"
          variant="outline"
          size="sm"
          disabled={isExporting}
          onClick={handleExport}
        >
          {isExporting ? (
            <Loader2 className="mr-1.5 h-3.5 w-3.5 animate-spin" />
          ) : (
            <Download className="mr-1.5 h-3.5 w-3.5" />
          )}
          Export CSV
        </Button>
      </div>
    </div>
  )
}

'use client'

import { useRouter } from 'next/navigation'
import { useSearchParams } from 'next/navigation'
import { useEffect } from 'react'
import { toast } from 'sonner'
import { Calendar, BookOpen } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Separator } from '@/components/ui/separator'
import { GoogleCalendarConnect } from './GoogleCalendarConnect'
import { QuickBooksExport } from './QuickBooksExport'
import type { CalendarSyncDirection } from '@/lib/supabase/types'

interface ArtistCalendarSync {
  id: string
  artistId: string
  artistName: string
  isActive: boolean
  syncDirection: CalendarSyncDirection
  provider: string
}

interface IntegrationsHubProps {
  artists: Array<{ id: string; first_name: string; last_name: string }>
  calendarSyncs: ArtistCalendarSync[]
  hasCalendarFeature: boolean
  hasPayrollFeature: boolean
}

const CAL_ERROR_MESSAGES: Record<string, string> = {
  denied: 'Google Calendar connection was cancelled',
  missing_params: 'Invalid OAuth callback parameters',
  invalid_state: 'OAuth state was invalid or expired — please try again',
  token_exchange: 'Failed to exchange authorization code — please try again',
  store_failed: 'Failed to save calendar tokens — please try again',
  server: 'An unexpected error occurred — please try again',
}

export function IntegrationsHub({
  artists,
  calendarSyncs,
  hasCalendarFeature,
  hasPayrollFeature,
}: IntegrationsHubProps) {
  const router = useRouter()
  const searchParams = useSearchParams()

  useEffect(() => {
    const calError = searchParams.get('cal_error')
    const calSuccess = searchParams.get('cal_success')
    if (calError) {
      toast.error(CAL_ERROR_MESSAGES[calError] ?? 'Calendar connection failed')
      router.replace('/settings/integrations')
    }
    if (calSuccess) {
      toast.success('Google Calendar connected')
      router.replace('/settings/integrations')
    }
  }, [searchParams, router])

  function getSyncForArtist(artistId: string): ArtistCalendarSync | null {
    return calendarSyncs.find((s) => s.artistId === artistId) ?? null
  }

  return (
    <div className="space-y-6">
      {/* Google Calendar */}
      <Card className="shadow-card">
        <CardHeader>
          <div className="flex items-center gap-2">
            <Calendar className="h-4 w-4 text-muted-foreground" />
            <CardTitle className="text-sm font-medium">Google Calendar</CardTitle>
          </div>
          <p className="text-xs text-muted-foreground">
            Sync artist bookings with their Google Calendar. Each artist connects their own account.
          </p>
        </CardHeader>
        <CardContent>
          {!hasCalendarFeature ? (
            <div className="rounded-lg border border-dashed border-border p-6 text-center">
              <p className="text-sm text-muted-foreground">
                Google Calendar sync requires the <strong>Studio+</strong> plan.
              </p>
            </div>
          ) : artists.length === 0 ? (
            <p className="text-sm text-muted-foreground">No artists in your studio yet.</p>
          ) : (
            <div className="space-y-4">
              {artists.map((artist, idx) => (
                <div key={artist.id}>
                  {idx > 0 && <Separator className="mb-4" />}
                  <GoogleCalendarConnect
                    artistId={artist.id}
                    artistName={`${artist.first_name} ${artist.last_name}`}
                    sync={getSyncForArtist(artist.id)}
                    onRefresh={() => router.refresh()}
                  />
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* QuickBooks */}
      <Card className="shadow-card">
        <CardHeader>
          <div className="flex items-center gap-2">
            <BookOpen className="h-4 w-4 text-muted-foreground" />
            <CardTitle className="text-sm font-medium">QuickBooks</CardTitle>
          </div>
          <p className="text-xs text-muted-foreground">
            Export financial data as QuickBooks-compatible CSV files.
          </p>
        </CardHeader>
        <CardContent>
          {!hasPayrollFeature ? (
            <div className="rounded-lg border border-dashed border-border p-6 text-center">
              <p className="text-sm text-muted-foreground">
                QuickBooks export requires the <strong>Pro</strong> plan.
              </p>
            </div>
          ) : (
            <QuickBooksExport />
          )}
        </CardContent>
      </Card>
    </div>
  )
}

import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { logAuditAction } from '@/lib/audit'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'

const UpdateLocationSchema = z.object({
  name: z.string().min(1).max(200).optional(),
  status: z.enum(['active', 'inactive', 'coming_soon']).optional(),
  timezone: z.string().max(100).optional(),
  phone: z.string().max(30).optional().nullable(),
  description: z.string().max(2000).optional().nullable(),
  street: z.string().max(200).optional().nullable(),
  city: z.string().max(100).optional().nullable(),
  state: z.string().max(100).optional().nullable(),
  zip: z.string().max(20).optional().nullable(),
  country: z.string().max(100).optional().nullable(),
  google_maps_url: z.string().url().optional().nullable(),
  social_instagram: z.string().max(100).optional().nullable(),
  cover_image_url: z.string().url().optional().nullable(),
  opening_hours: z.array(z.object({
    day: z.number().int().min(0).max(6),
    open: z.string(),
    close: z.string(),
    closed: z.boolean().optional(),
  })).optional().nullable(),
  sort_order: z.number().int().optional(),
})

type RouteParams = { params: Promise<{ id: string }> }

export async function GET(_req: NextRequest, { params }: RouteParams) {
  const { id } = await params
  const supabase = await createClient()

  const { data: { user }, error: authError } = await supabase.auth.getUser()
  if (!user || authError) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(user.id)
  if (!success) return Response.json({ error: 'Too many requests' }, { status: 429 })

  // Verify location belongs to user's studio
  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .single()
  if (!member) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: location, error } = await supabase
    .from('locations')
    .select('*')
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .single()

  if (error || !location) return Response.json({ error: 'Not found' }, { status: 404 })

  return Response.json({ data: location })
}

export async function PATCH(req: NextRequest, { params }: RouteParams) {
  const { id } = await params
  const supabase = await createClient()

  const { data: { user }, error: authError } = await supabase.auth.getUser()
  if (!user || authError) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(user.id)
  if (!success) return Response.json({ error: 'Too many requests' }, { status: 429 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .single()
  if (!member) return Response.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(member.role)) {
    return Response.json({ error: 'Forbidden' }, { status: 403 })
  }

  // Verify location belongs to studio
  const { data: existing } = await supabase
    .from('locations')
    .select('id')
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .single()
  if (!existing) return Response.json({ error: 'Not found' }, { status: 404 })

  const body: unknown = await req.json()
  const parsed = UpdateLocationSchema.safeParse(body)
  if (!parsed.success) {
    return Response.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { opening_hours, ...rest } = parsed.data

  const { data: updated, error } = await supabase
    .from('locations')
    .update({
      ...rest,
      ...(opening_hours !== undefined ? { opening_hours: opening_hours as unknown as import('@/lib/supabase/types').Database['public']['Tables']['locations']['Update']['opening_hours'] } : {}),
    })
    .eq('id', id)
    .select()
    .single()

  if (error || !updated) {
    logger.error({ err: error, locationId: id }, 'location update failed')
    return Response.json({ error: 'Failed to update location' }, { status: 500 })
  }

  await logAuditAction({
    actor_id: user.id,
    action: 'location.update',
    target_type: 'location',
    target_id: id,
    studio_id: member.studio_id,
    details: { fields: Object.keys(parsed.data) },
  })

  return Response.json({ data: updated })
}

export async function DELETE(_req: NextRequest, { params }: RouteParams) {
  const { id } = await params
  const supabase = await createClient()

  const { data: { user }, error: authError } = await supabase.auth.getUser()
  if (!user || authError) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(user.id)
  if (!success) return Response.json({ error: 'Too many requests' }, { status: 429 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .single()
  if (!member) return Response.json({ error: 'Unauthorized' }, { status: 401 })
  if (member.role !== 'owner') {
    return Response.json({ error: 'Only owners can delete locations' }, { status: 403 })
  }

  // Verify ownership
  const { data: existing } = await supabase
    .from('locations')
    .select('id, name')
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .single()
  if (!existing) return Response.json({ error: 'Not found' }, { status: 404 })

  const { error } = await supabase
    .from('locations')
    .delete()
    .eq('id', id)

  if (error) {
    logger.error({ err: error, locationId: id }, 'location delete failed')
    return Response.json({ error: 'Failed to delete location' }, { status: 500 })
  }

  await logAuditAction({
    actor_id: user.id,
    action: 'location.delete',
    target_type: 'location',
    target_id: id,
    studio_id: member.studio_id,
    details: { name: existing.name },
  })

  return new Response(null, { status: 204 })
}

