import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { checkFeatureRpc } from '@/lib/billing/feature-gate'
import { LocationsGrid } from '@/components/locations/LocationsGrid'
import { UpgradeGatePageBlock } from '@/components/billing/UpgradeGate'
import type { LocationStatus, MultiLocationOverview } from '@/lib/supabase/types'

export const metadata: Metadata = {
  title: 'Locations — InkOS',
}

export default async function LocationsPage() {
  const supabase = await createClient()

  const { data: { user } } = await supabase.auth.getUser()
  if (!user) redirect('/login')

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) redirect('/onboarding')

  const studioId = member.studio_id
  const canManage = ['owner', 'admin'].includes(member.role)
  const hasMultiLocation = await checkFeatureRpc(supabase, studioId, 'multi_location')

  if (!hasMultiLocation) {
    return (
      <div className="p-6 max-w-2xl">
        <UpgradeGatePageBlock
          requiredPlan="pro"
          feature="Multi-location management"
          description="Manage multiple studio locations, assign artists, override services, and view rollup analytics across all sites."
        />
      </div>
    )
  }

  const { data: rawLocations } = await supabase
    .from('locations')
    .select(`
      id, name, status, city, state, timezone,
      street, cover_image_url, sort_order, manager_id
    `)
    .eq('studio_id', studioId)
    .order('sort_order', { ascending: true })
    .order('created_at', { ascending: true })

  const locList = rawLocations ?? []

  // Enrich each location with counts and manager name
  const locations = await Promise.all(
    locList.map(async (loc, idx) => {
      const [artistRes, bookingRes, managerRes] = await Promise.all([
        supabase
          .from('location_assignments')
          .select('id', { count: 'exact', head: true })
          .eq('location_id', loc.id)
          .eq('is_active', true),
        supabase
          .from('appointments')
          .select('id', { count: 'exact', head: true })
          .eq('location_id', loc.id)
          .gte(
            'start_at',
            new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString(),
          ),
        loc.manager_id
          ? supabase
              .from('profiles')
              .select('first_name, last_name')
              .eq('id', loc.manager_id)
              .single()
          : Promise.resolve({ data: null }),
      ])

      const managerData = managerRes.data as { first_name: string; last_name: string } | null

      return {
        id: loc.id,
        name: loc.name,
        address: loc.street ?? null,
        city: loc.city ?? null,
        state: loc.state ?? null,
        status: loc.status as LocationStatus,
        is_primary: idx === 0, // first location by sort_order is primary
        manager: managerData
          ? { full_name: `${managerData.first_name} ${managerData.last_name}` }
          : null,
        artist_count: artistRes.count ?? 0,
        bookings_this_month: bookingRes.count ?? 0,
        opening_hours_summary: null, // compute if needed
      }
    }),
  )

  // Fetch overview RPC (only when >1 location)
  let overview: MultiLocationOverview | null = null
  if (locations.length > 1) {
    const { data: overviewData } = await supabase.rpc('get_multi_location_overview', {
      p_studio_id: studioId,
    })
    if (overviewData) {
      overview = overviewData as unknown as MultiLocationOverview
    }
  }

  return (
    <div className="p-6">
      <LocationsGrid
        locations={locations}
        overview={overview}
        canManage={canManage}
      />
    </div>
  )
}

import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { logAuditAction } from '@/lib/audit'
import { authedRatelimit } from '@/lib/rate-limit'
import { requireFeatureRpc, FeatureGateError } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import type { Json } from '@/lib/supabase/types'

const CreateLocationSchema = z.object({
  name: z.string().min(1, 'Name is required').max(200),
  status: z.enum(['active', 'inactive', 'coming_soon']).default('active'),
  timezone: z.string().max(100).default('America/New_York'),
  phone: z.string().max(30).optional().nullable(),
  description: z.string().max(2000).optional().nullable(),
  address: z.string().max(300).optional().nullable(),
  city: z.string().max(100).optional().nullable(),
  state: z.string().max(100).optional().nullable(),
  zip: z.string().max(20).optional().nullable(),
  country: z.string().max(100).default('US'),
  google_maps_url: z.string().url().max(2048).optional().nullable().or(z.literal('')),
  social_instagram: z.string().max(200).optional().nullable(),
  cover_image_url: z.string().url().optional().nullable(),
  opening_hours: z.array(z.object({
    day_of_week: z.number().int().min(0).max(6),
    open_time: z.string(),
    close_time: z.string(),
  })).default([]),
})

export async function POST(req: NextRequest) {
  const supabase = await createClient()

  const { data: { user }, error: authError } = await supabase.auth.getUser()
  if (!user || authError) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(user.id)
  if (!success) return Response.json({ error: 'Too many requests' }, { status: 429 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(member.role)) {
    return Response.json({ error: 'Forbidden' }, { status: 403 })
  }

  try {
    await requireFeatureRpc(supabase, member.studio_id, 'multi_location')
  } catch (e) {
    if (e instanceof FeatureGateError) {
      return Response.json(
        { error: 'Multi-location requires Pro plan or above', requiredPlan: 'pro' },
        { status: 403 },
      )
    }
    throw e
  }

  const body: unknown = await req.json()
  const parsed = CreateLocationSchema.safeParse(body)
  if (!parsed.success) {
    return Response.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { opening_hours, google_maps_url, ...rest } = parsed.data

  const { data: location, error } = await supabase
    .from('locations')
    .insert({
      ...rest,
      studio_id: member.studio_id,
      opening_hours: opening_hours as unknown as Json,
      google_maps_url: google_maps_url || null,
    })
    .select()
    .single()

  if (error || !location) {
    logger.error({ err: error, studioId: member.studio_id }, 'location create failed')
    return Response.json({ error: 'Failed to create location' }, { status: 500 })
  }

  await logAuditAction({
    actor_id: user.id,
    action: 'location.create',
    target_type: 'location',
    target_id: location.id,
    studio_id: member.studio_id,
    details: { name: location.name },
  })

  return Response.json({ data: location }, { status: 201 })
}

