import type { Metadata } from 'next'
import { redirect, notFound } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { checkFeatureRpc } from '@/lib/billing/feature-gate'
import { LocationDashboard } from '@/components/locations/LocationDashboard'
import { LocationForm } from '@/components/locations/LocationForm'
import { ArtistAssignments } from '@/components/locations/ArtistAssignments'
import { ServiceOverrides } from '@/components/locations/ServiceOverrides'
import { PageHeader } from '@/components/shared/PageHeader'
import type { LocationDashboardData, LocationStatus } from '@/lib/supabase/types'

export const metadata: Metadata = {
  title: 'Location — InkOS',
}

type PageProps = { params: Promise<{ id: string }> }

export default async function LocationDetailPage({ params }: PageProps) {
  const { id } = await params
  const supabase = await createClient()

  const { data: { user } } = await supabase.auth.getUser()
  if (!user) redirect('/login')

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) redirect('/onboarding')

  const studioId = member.studio_id
  const canManage = ['owner', 'admin'].includes(member.role)

  // Verify location belongs to studio
  const { data: location } = await supabase
    .from('locations')
    .select('id, name, status, address, city, state, zip, country, timezone, phone, description, google_maps_url, social_instagram, cover_image_url, sort_order, opening_hours, manager_id')
    .eq('id', id)
    .eq('studio_id', studioId)
    .single()

  if (!location) notFound()

  // Parallel fetches
  const hasMultiLocation = await checkFeatureRpc(supabase, studioId, 'multi_location')

  const [dashboardResult, assignmentsResult, artistsResult, servicesResult] = await Promise.all([
    supabase.rpc('get_location_dashboard', { p_location_id: id, p_studio_id: studioId }),
    supabase
      .from('location_assignments')
      .select('id, is_primary, artist_id, artist:artists(id, display_name, avatar_url, status)')
      .eq('location_id', id)
      .eq('is_active', true)
      .order('is_primary', { ascending: false }),
    supabase
      .from('artists')
      .select('id, display_name, avatar_url')
      .eq('studio_id', studioId)
      .eq('status', 'active')
      .order('display_name'),
    supabase
      .from('location_service_overrides')
      .select(`
        service_id,
        is_available,
        price_override_cents,
        duration_override_min,
        service:services(id, name, duration_min, price_cents, color)
      `)
      .eq('location_id', id),
  ])

  const dashboardData = dashboardResult.data as unknown as LocationDashboardData | null

  type RawAssignment = {
    id: string
    is_primary: boolean
    artist_id: string
    artist: { id: string; display_name: string; avatar_url: string | null; status: string } | null
  }

  const assignments = (assignmentsResult.data ?? []) as RawAssignment[]

  const mappedAssignments = assignments.map((a) => ({
    id: a.id,
    is_primary: a.is_primary,
    artist: a.artist
      ? { id: a.artist.id, display_name: a.artist.display_name, avatar_url: a.artist.avatar_url, status: a.artist.status }
      : null,
  }))

  type RawOverride = {
    service_id: string
    is_available: boolean
    price_override_cents: number | null
    duration_override_min: number | null
    service: { id: string; name: string; duration_min: number; price_cents: number; color: string | null } | null
  }

  const rawOverrides = (servicesResult.data ?? []) as unknown as RawOverride[]

  // Also get all studio services to show unoverridden ones
  const { data: allServices } = await supabase
    .from('services')
    .select('id, name, duration_min, price_cents, color')
    .eq('studio_id', studioId)
    .eq('is_active', true)
    .order('name')

  // Merge overrides with all services
  const overrideMap = new Map(rawOverrides.map((o) => [o.service_id, o]))
  const services = (allServices ?? []).map((svc) => {
    const override = overrideMap.get(svc.id)
    return {
      service_id: svc.id,
      service_name: svc.name,
      service_duration_min: svc.duration_min,
      service_base_price_cents: svc.price_cents,
      service_color: svc.color,
      is_available: override?.is_available ?? true,
      price_override_cents: override?.price_override_cents ?? null,
      duration_override_min: override?.duration_override_min ?? null,
    }
  })

  // Build form default values
  const openingHoursRaw = location.opening_hours as unknown
  const openingHoursArray = Array.isArray(openingHoursRaw)
    ? (openingHoursRaw as Array<{ day_of_week: number; open_time: string; close_time: string }>)
    : []

  return (
    <div className="p-6 space-y-8">
      <PageHeader
        title={location.name}
        subtitle={[location.city, location.state].filter(Boolean).join(', ') || 'Location details'}
      />

      {/* Dashboard metrics */}
      {dashboardData && hasMultiLocation && (
        <section>
          <h2 className="mb-3 text-xs font-semibold uppercase tracking-widest text-muted-foreground">
            This month
          </h2>
          <LocationDashboard data={dashboardData} />
        </section>
      )}

      {/* Edit form */}
      <section>
        <h2 className="mb-4 text-xs font-semibold uppercase tracking-widest text-muted-foreground">
          Location settings
        </h2>
        <LocationForm
          mode="edit"
          locationId={id}
          defaultValues={{
            name: location.name,
            status: location.status as LocationStatus,
            timezone: location.timezone,
            phone: location.phone ?? undefined,
            description: location.description ?? undefined,
            address: location.address ?? undefined,
            city: location.city ?? undefined,
            state: location.state ?? undefined,
            zip: location.zip ?? undefined,
            country: location.country,
            google_maps_url: location.google_maps_url ?? undefined,
            social_instagram: location.social_instagram ?? undefined,
            opening_hours: openingHoursArray,
          }}
        />
      </section>

      {/* Artist assignments */}
      {hasMultiLocation && (
        <section>
          <h2 className="mb-4 text-xs font-semibold uppercase tracking-widest text-muted-foreground">
            Artists
          </h2>
          <ArtistAssignments
            locationId={id}
            locationName={location.name}
            assignments={mappedAssignments}
            allArtists={(artistsResult.data ?? []).map((a) => ({
              id: a.id,
              display_name: a.display_name,
              avatar_url: a.avatar_url,
            }))}
            canManage={canManage}
          />
        </section>
      )}

      {/* Service overrides */}
      {hasMultiLocation && services.length > 0 && (
        <section>
          <h2 className="mb-4 text-xs font-semibold uppercase tracking-widest text-muted-foreground">
            Services
          </h2>
          <ServiceOverrides
            locationId={id}
            services={services}
            canManage={canManage}
          />
        </section>
      )}
    </div>
  )
}

