          description="Remove InkOS branding and use your own domain on client-facing pages. Available on the Enterprise plan."
        />
      ) : (
        <>
          <BrandingSettings
            whiteLabelEnabled={studio?.white_label_enabled ?? false}
            poweredByHidden={studio?.powered_by_hidden ?? false}
            customFaviconUrl={studio?.custom_favicon_url ?? null}
            customEmailFromName={studio?.custom_email_from_name ?? null}
            customEmailReplyTo={studio?.custom_email_reply_to ?? null}
            canEdit={canEdit}
          />

          <DomainVerification
            currentDomain={studio?.custom_domain ?? null}
            isVerified={studio?.custom_domain_verified ?? false}
            verifiedAt={studio?.custom_domain_verified_at ?? null}
            verificationError={latestVerification?.error ?? null}
            canEdit={canEdit}
          />
        </>
      )}
    </div>
  )
}

