  const { data: locations } = await supabase
    .from('locations')
    .select('id, name')
    .eq('studio_id', studioId)
    .eq('status', 'active')
    .order('name')

  return (
    <div className="p-6 max-w-3xl">
      <PageHeader
        title="New campaign"
        subtitle="Build your message, target your audience, and schedule or send."
