        mode="create"
        studioId={studioId}
        locationOptions={(locations ?? []).map((l) => ({ id: l.id, name: l.name }))}
      />
    </div>
  )
}

import { type NextRequest, NextResponse } from 'next/server'
import { updateSession } from '@/lib/supabase/middleware'
import { createServerClient } from '@supabase/ssr'
import type { Database } from '@/lib/supabase/types'

/**
 * Next.js 16 middleware — renamed from middleware.ts to proxy.ts.
 *
 * Runs on every matched request to:
 * 1. Handle custom domain rewrites (verified domains only — host header attack prevention)
 * 2. Refresh the Supabase session.
 * 3. Redirect unauthenticated requests to protected routes → /login.
 */
export async function proxy(request: NextRequest) {
  const host = request.headers.get('host') ?? ''
  const appHost = new URL(process.env.NEXT_PUBLIC_APP_URL ?? 'http://localhost:3000').host

  // Custom domain rewrite — only runs when the host is NOT the primary app host
  // This prevents host header injection: we verify the domain exists and is verified in DB
  if (host && host !== appHost && !host.startsWith('localhost')) {
    const supabase = createServerClient<Database>(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
      {
        cookies: {
          getAll() {
            return request.cookies.getAll()
          },
          // Read-only in middleware domain check — no cookie writes needed here
          setAll() {},
        },
      },
    )

    // Only rewrite if the custom_domain is verified — never rewrite unverified domains
    const { data: studio } = await supabase
      .from('studios')
      .select('slug')
      .eq('custom_domain', host)
      .eq('custom_domain_verified', true)
      .eq('white_label_enabled', true)
      .maybeSingle()

    if (studio?.slug) {
      const url = request.nextUrl.clone()
      // Rewrite to the public booking page for this studio
      url.pathname = `/book/${studio.slug}${url.pathname === '/' ? '' : url.pathname}`
      return NextResponse.rewrite(url)
    }

    // Domain not found or not verified — return 404 to prevent info leakage
    if (!host.endsWith(`.${appHost}`)) {
      return new NextResponse('Not found', { status: 404 })
    }
  }

  return updateSession(request)
}

export const config = {
  matcher: [
    /*
     * Match all request paths except:
     * - _next/static (static files)
     * - _next/image (image optimization)
     * - favicon.ico
     * - public folder files
     * - api/webhooks (webhook endpoints must not have session refresh overhead)
     */
    '/((?!_next/static|_next/image|favicon.ico|api/webhooks|.*\\.(?:svg|png|jpg|jpeg|gif|webp|ico|css|js)$).*)',
  ],
}

